    if(i===0)d1=d2;if(i===P.length-1)d2=d1;let tx=d1[0]+d2[0],ty=d1[1]+d2[1];const tl=Math.hypot(tx,ty);if(tl<1e-3){tx=d1[0];ty=d1[1]}else{tx/=tl;ty/=tl}
