  for(let i=0;i<P.length-1;i++){const a=P[i],b=P[i+1],na=N[i],nb=N[i+1];V(a,na);V(a,[-na[0],-na[1]]);V(b,nb);V(a,[-na[0],-na[1]]);V(b,[-nb[0],-nb[1]]);V(b,nb)}
